<?php
namespace App\Filament\Resources\TireRequests\Schemas;
use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\Toggle; use Filament\Schemas\Schema;
class TireRequestForm { public static function configure(Schema $schema): Schema { return $schema->components([Select::make('registration_id')->relationship('registration','id')->required(), Select::make('motorcycle_id')->relationship('motorcycle','model')->required(), Toggle::make('brings_own_tires'), TextInput::make('own_extra_sets_count')->numeric()->minValue(0)->maxValue(2)->default(0), Toggle::make('wants_tire_service'), Toggle::make('wants_to_order_tires'), TextInput::make('preferred_brand')->default('Pirelli'), TextInput::make('front_tire_size'), TextInput::make('rear_tire_size'), TextInput::make('compound_preference'), Textarea::make('notes'), Select::make('status')->options(['open'=>'Open','confirmed'=>'Confirmed','ordered'=>'Ordered','completed'=>'Completed','cancelled'=>'Cancelled'])->required()]); } }
